      (excluded.naam, excluded.merk, excluded.groep, excluded.energie_kcal_per_100g, excluded.eiwit_g, excluded.vet_g, excluded.koolhydraten_g, excluded.vezels_g, excluded.suikers_g, excluded.verpakking_gram, excluded.portie_gram, excluded.portie_naam);

-- Nakijken:
select count(*) as producten, count(verpakking_gram) as met_gewicht from merk_producten where bron = 'openfoodfacts';

